#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    vector<int> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }

    vector<int> b;
    long long max_value = 0;
    int half = (n / 2) + (n % 2);
    int limit1 = 1 << half;

    for (int i = 0; i < limit1; ++i) {
        long long total = 0;
        int mask = i;
        for (int j = 0; j < 20; ++j) {
            if (mask & 1) {
                total += a[j];
            }
            mask >>= 1;
        }
        b.push_back((int)(total % m));
    }

    sort(b.begin(), b.end());

    int limit2 = 1 << (n / 2);
    for (int i = 0; i < limit2; ++i) {
        long long total = 0;
        int mask = i;
        for (int j = 0; j < 20; ++j) {
            if (mask & 1) {
                total += a[(n / 2) + (n % 2) + j];
            }
            mask >>= 1;
        }
        total %= m;
        int index = (int)(std::lower_bound(b.begin(), b.end(), m - total - 1) - b.begin());
        int candidate;
        if (index < (int)b.size()) {
            candidate = b[index];
            if (candidate > m - total - 1 && index - 1 >= 0) {
                candidate = b[index - 1];
            }
        } else {
            candidate = b.back();
        }
        max_value = max(max_value, (total + candidate) % m);
        max_value = max(max_value, (total + b.back()) % m);
    }
    cout << max_value % m << "\n";
    return 0;
}
